// Generate a 6-character uppercase alphanumeric party code
const CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // base32-ish, unambiguous chars
function generateCode() {
  let code = '';
  for (let i = 0; i < 6; i++) {
    code += CHARS.charAt(Math.floor(Math.random() * CHARS.length));
  }
  return code;
}

// Generate a secure join token (32 hex chars)
function generateToken() {
  const arr = new Uint8Array(16);
  crypto.getRandomValues(arr);
  return Array.from(arr).map(b => b.toString(16).padStart(2, '0')).join('');
}

const body = $input.first().json.body || $input.first().json;
const partyCode  = generateCode();
const joinToken  = generateToken();

return [{
  json: {
    party_code:      partyCode,
    restaurant_name: body.restaurant_name || null,
    tip_percent:     parseFloat(body.tip_percent) || 0,
    user_id:         body.user_id || null,
    display_name:    body.display_name || 'Host',
    join_token:      joinToken
  }
}];

